
CREATE TABLE companies (
    company_id VARCHAR(50) PRIMARY KEY,
    company_name VARCHAR(255),
    product_name VARCHAR(255),
    description TEXT,
    employees INT,
    revenue BIGINT,
    invest_count INT,
    invest_level VARCHAR(100),
    hiring BOOLEAN
);
CREATE TABLE categories (
    category_id SERIAL PRIMARY KEY,
    category_name VARCHAR(255) UNIQUE
);
CREATE TABLE keywords (
    keyword_id SERIAL PRIMARY KEY,
    keyword_name VARCHAR(255) UNIQUE
);
CREATE TABLE company_categories (
    company_id VARCHAR(50) REFERENCES companies(company_id),
    category_id INT REFERENCES categories(category_id),
    PRIMARY KEY (company_id, category_id)
);
CREATE TABLE company_keywords (
    company_id VARCHAR(50) REFERENCES companies(company_id),
    keyword_id INT REFERENCES keywords(keyword_id),
    PRIMARY KEY (company_id, keyword_id)
);

